head.b:skin:
/* ==========================================================================
   Rajasthan SSO Guide - Modern High-Performance Blogger Stylesheet
   Optimized for Core Web Vitals, SEO, Ad Placements & Mobile Usability
   ========================================================================== */

:root {
  --primary: #0f2942;
  --primary-dark: #0a1b2c;
  --primary-light: #1e3a8a;
  --secondary: #ea580c;
  --secondary-hover: #c2410c;
  --accent: #f59e0b;
  --accent-light: #fef3c7;
  --success: #16a34a;
  --info: #0284c7;
  --warning: #d97706;
  --danger: #dc2626;

  --bg-page: #f8fafc;
  --bg-surface: #ffffff;
  --bg-subtle: #f1f5f9;
  --bg-card: #ffffff;
  --border-color: #e2e8f0;
  --border-light: #edf2f7;

  --text-main: #0f172a;
  --text-muted: #475569;
  --text-light: #94a3b8;
  --text-on-primary: #ffffff;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -1px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -2px rgba(0, 0, 0, 0.03);
  --shadow-hover: 0 20px 25px -5px rgba(15, 41, 66, 0.1), 0 10px 10px -5px rgba(15, 41, 66, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Mukta", "Noto Sans Devanagari", Oxygen, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
  --container-width: 1200px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

[data-theme="dark"] {
  --primary: #1e293b;
  --primary-dark: #0f172a;
  --primary-light: #334155;
  --bg-page: #0b0f17;
  --bg-surface: #131b26;
  --bg-subtle: #1a2332;
  --bg-card: #151e2c;
  --border-color: #232f42;
  --border-light: #1b2637;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --text-light: #64748b;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4);
}

/* Base Resets */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-main);
  background-color: var(--bg-page);
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--primary-light);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--secondary);
}

p {
  margin-bottom: 1.15rem;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--text-main);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 0.75rem;
}

h1 { font-size: clamp(1.8rem, 3.5vw, 2.6rem); }
h2 { font-size: clamp(1.4rem, 2.5vw, 1.9rem); margin-top: 1.5rem; }
h3 { font-size: clamp(1.15rem, 2vw, 1.4rem); margin-top: 1.25rem; }

ul, ol {
  padding-left: 1.5rem;
  margin-bottom: 1.25rem;
}

li {
  margin-bottom: 0.35rem;
}

.container {
  width: 100%;
  max-width: var(--container-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */

/* Top Official Ticker Bar */
.gov-top-bar {
  background: linear-gradient(90deg, #091a2b 0%, #0f2942 50%, #173657 100%);
  color: #e2e8f0;
  font-size: 0.8125rem;
  padding: 0.35rem 0;
  border-bottom: 2px solid var(--secondary);
}

.gov-top-bar .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.ticker-wrap {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  overflow: hidden;
  white-space: nowrap;
}

.ticker-badge {
  background-color: var(--secondary);
  color: #fff;
  font-weight: 700;
  font-size: 0.7rem;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  animation: pulseBadge 2s infinite;
}

@keyframes pulseBadge {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.ticker-content {
  overflow: hidden;
  text-overflow: ellipsis;
}

.top-bar-links {
  display: flex;
  align-items: center;
  gap: 1rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.top-bar-links a {
  color: #cbd5e1;
  font-size: 0.78rem;
}

.top-bar-links a:hover {
  color: var(--accent);
}

/* Main Site Header */
.site-header {
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.brand-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
}

.brand-title {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1.1;
}

[data-theme="dark"] .brand-title {
  color: #f8fafc;
}

.brand-title span {
  color: var(--secondary);
}

.brand-tagline {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 1.25rem;
  margin: 0;
  padding: 0;
}

.nav-links a {
  color: var(--text-main);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.5rem 0.25rem;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--secondary);
}

.nav-links a.active::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--secondary);
  border-radius: 2px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Action Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  border: 1px solid transparent;
  transition: var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: linear-gradient(135deg, var(--secondary) 0%, #c2410c 100%);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(234, 88, 12, 0.25);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #c2410c 0%, #9a3412 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(234, 88, 12, 0.35);
  color: #fff;
}

.btn-secondary {
  background: var(--primary);
  color: #ffffff;
}

.btn-secondary:hover {
  background: var(--primary-light);
  color: #ffffff;
}

.btn-outline {
  border-color: var(--border-color);
  background: var(--bg-surface);
  color: var(--text-main);
}

.btn-outline:hover {
  border-color: var(--secondary);
  color: var(--secondary);
}

.btn-sm {
  padding: 0.4rem 0.75rem;
  font-size: 0.8125rem;
  border-radius: var(--radius-sm);
}

.btn-lg {
  padding: 0.875rem 1.75rem;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
}

.theme-toggle-btn,
.mobile-menu-toggle {
  background: none;
  border: 1px solid var(--border-color);
  color: var(--text-main);
  padding: 0.5rem;
  border-radius: var(--radius-md);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.theme-toggle-btn:hover,
.mobile-menu-toggle:hover {
  background-color: var(--bg-subtle);
}

.mobile-menu-toggle {
  display: none;
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  background: radial-gradient(circle at 80% 20%, rgba(245, 158, 11, 0.12), transparent 45%),
              linear-gradient(180deg, var(--bg-surface) 0%, var(--bg-subtle) 100%);
  padding: 3rem 0 2.5rem;
  border-bottom: 1px solid var(--border-color);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.25fr 0.95fr;
  gap: 2.5rem;
  align-items: center;
}

.verified-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: #ecfdf5;
  color: #065f46;
  border: 1px solid #a7f3d0;
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

[data-theme="dark"] .verified-pill {
  background-color: #064e3b;
  color: #6ee7b7;
  border-color: #047857;
}

.hero-title {
  color: var(--primary);
  margin-bottom: 1rem;
  line-height: 1.2;
}

[data-theme="dark"] .hero-title {
  color: #ffffff;
}

.hero-title .highlight {
  color: var(--secondary);
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin-bottom: 1.5rem;
}

.quick-stats-row {
  display: flex;
  gap: 1.75rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-color);
}

.stat-item {
  display: flex;
  flex-direction: column;
}

.stat-number {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--primary);
}

[data-theme="dark"] .stat-number {
  color: var(--accent);
}

.stat-label {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* Quick Action Card Box (Hero right side) */
.portal-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}

.portal-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: linear-gradient(90deg, #ea580c 0%, #f59e0b 50%, #0f2942 100%);
}

.portal-card-header {
  margin-bottom: 1.25rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid var(--border-color);
}

.portal-card-title {
  font-size: 1.2rem;
  margin-bottom: 0.25rem;
}

.portal-card-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.direct-buttons-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.85rem;
  margin-bottom: 1.25rem;
}

.portal-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 1rem 0.75rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background-color: var(--bg-surface);
  transition: var(--transition);
  cursor: pointer;
  text-decoration: none;
}

.portal-btn:hover {
  border-color: var(--secondary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.portal-btn-primary {
  background: linear-gradient(135deg, #0f2942 0%, #1e3a8a 100%);
  color: #fff;
  border-color: transparent;
}

.portal-btn-primary:hover {
  background: linear-gradient(135deg, #0a1b2c 0%, #172554 100%);
  color: #fff;
}

.portal-btn-secondary {
  background: linear-gradient(135deg, #ea580c 0%, #d97706 100%);
  color: #fff;
  border-color: transparent;
}

.portal-btn-secondary:hover {
  background: linear-gradient(135deg, #c2410c 0%, #b45309 100%);
  color: #fff;
}

.portal-btn-icon {
  font-size: 1.5rem;
  margin-bottom: 0.35rem;
}

.portal-btn-label {
  font-weight: 700;
  font-size: 0.9rem;
}

.portal-btn-sub {
  font-size: 0.72rem;
  opacity: 0.85;
}

.portal-card-note {
  font-size: 0.78rem;
  color: var(--text-muted);
  background-color: var(--bg-subtle);
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* ==========================================================================
   Interactive SSO Verification Tool
   ========================================================================== */
.tool-section {
  padding: 2.5rem 0;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
}

.tool-card {
  background: linear-gradient(135deg, #f8fafc 0%, #edf2f7 100%);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
}

[data-theme="dark"] .tool-card {
  background: linear-gradient(135deg, #131b26 0%, #1a2332 100%);
}

.tool-header {
  text-align: center;
  max-width: 650px;
  margin: 0 auto 1.5rem;
}

.tool-input-group {
  display: flex;
  max-width: 600px;
  margin: 0 auto;
  gap: 0.5rem;
}

.tool-input {
  flex: 1;
  padding: 0.75rem 1.25rem;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  font-size: 1rem;
  background-color: var(--bg-surface);
  color: var(--text-main);
  outline: none;
  transition: var(--transition);
}

.tool-input:focus {
  border-color: var(--secondary);
  box-shadow: 0 0 0 3px rgba(234, 88, 12, 0.15);
}

.tool-result {
  max-width: 600px;
  margin: 1rem auto 0;
  display: none;
  padding: 1rem;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
}

.tool-result.show {
  display: block;
}

.tool-result.valid {
  background-color: #ecfdf5;
  color: #065f46;
  border: 1px solid #6ee7b7;
}

.tool-result.invalid {
  background-color: #fef2f2;
  color: #991b1b;
  border: 1px solid #fca5a5;
}

/* ==========================================================================
   Services Grid / Quick Directory
   ========================================================================== */
.services-section {
  padding: 3rem 0;
}

.section-head {
  text-align: center;
  max-width: 750px;
  margin: 0 auto 2.5rem;
}

.section-tag {
  color: var(--secondary);
  font-weight: 700;
  text-transform: uppercase;
  font-size: 0.8125rem;
  letter-spacing: 1px;
  margin-bottom: 0.35rem;
  display: inline-block;
}

.services-filter-bar {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.filter-btn {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 0.4rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  transition: var(--transition);
}

.filter-btn:hover,
.filter-btn.active {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.25rem;
}

.service-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.35rem;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  transform: translateY(-3px);
  border-color: var(--secondary);
  box-shadow: var(--shadow-md);
}

.service-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.85rem;
}

.service-icon-box {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background-color: var(--bg-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
}

.service-category-badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
  background-color: var(--bg-subtle);
  color: var(--text-muted);
  text-transform: uppercase;
}

.service-title {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.service-hindi-title {
  font-size: 0.82rem;
  color: var(--secondary);
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.service-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
  flex: 1;
}

.service-link {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--secondary);
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.service-link:hover {
  gap: 0.6rem;
}

/* ==========================================================================
   Featured Blog Posts / Articles Section
   ========================================================================== */
.articles-section {
  padding: 3.5rem 0;
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 2rem;
}

.article-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--border-color);
}

.article-thumb-wrapper {
  position: relative;
  height: 200px;
  background: linear-gradient(135deg, #0f2942 0%, #1e3a8a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  color: #fff;
  text-align: center;
}

.article-thumb-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.1;
  background-image: radial-gradient(#fff 1px, transparent 1px);
  background-size: 16px 16px;
}

.article-thumb-badge {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background-color: var(--secondary);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  text-transform: uppercase;
}

.article-thumb-icon {
  font-size: 3.5rem;
  margin-bottom: 0.5rem;
  z-index: 1;
}

.article-content {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.article-meta {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.article-title {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
  line-height: 1.35;
}

.article-title a {
  color: var(--text-main);
}

.article-title a:hover {
  color: var(--secondary);
}

.article-excerpt {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
  flex: 1;
}

.article-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.85rem;
}

.article-author {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  color: var(--text-main);
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background-color: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
}

/* ==========================================================================
   Comprehensive SEO Guide (In-Depth Content Section)
   ========================================================================== */
.guide-content-section {
  padding: 3.5rem 0;
}

.content-layout {
  display: grid;
  grid-template-columns: 2.2fr 1fr;
  gap: 2.5rem;
}

.guide-article {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
}

.table-of-contents {
  background-color: var(--bg-subtle);
  border-left: 4px solid var(--secondary);
  padding: 1.25rem 1.5rem;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  margin: 1.5rem 0 2.5rem;
}

.toc-title {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  color: var(--primary);
}

[data-theme="dark"] .toc-title {
  color: #fff;
}

.toc-list {
  list-style: none;
  padding-left: 0;
  margin: 0;
}

.toc-list li {
  margin-bottom: 0.4rem;
}

.toc-list a {
  color: var(--text-muted);
  font-size: 0.9rem;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.toc-list a:hover {
  color: var(--secondary);
  transform: translateX(4px);
}

/* Step-by-Step Timeline Box */
.timeline-steps {
  margin: 2rem 0;
  position: relative;
  padding-left: 2rem;
}

.timeline-steps::before {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 12px;
  width: 2px;
  background-color: var(--border-color);
}

.step-item {
  position: relative;
  margin-bottom: 2rem;
}

.step-item:last-child {
  margin-bottom: 0;
}

.step-marker {
  position: absolute;
  left: -2rem;
  top: 0;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background-color: var(--secondary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 0 4px var(--bg-card);
}

.step-body h4 {
  font-size: 1.15rem;
  margin-bottom: 0.4rem;
}

/* Informational Callouts */
.callout {
  padding: 1.25rem;
  border-radius: var(--radius-md);
  margin: 1.5rem 0;
  display: flex;
  gap: 1rem;
}

.callout-info {
  background-color: #eff6ff;
  border-left: 4px solid var(--info);
  color: #1e40af;
}

[data-theme="dark"] .callout-info {
  background-color: #172554;
  color: #93c5fd;
}

.callout-warning {
  background-color: #fffbeb;
  border-left: 4px solid var(--warning);
  color: #92400e;
}

[data-theme="dark"] .callout-warning {
  background-color: #451a03;
  color: #fde68a;
}

/* Tables */
.responsive-table {
  width: 100%;
  overflow-x: auto;
  margin: 1.5rem 0;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  text-align: left;
}

th {
  background-color: var(--bg-subtle);
  color: var(--text-main);
  font-weight: 700;
  padding: 0.85rem 1rem;
  border-bottom: 2px solid var(--border-color);
}

td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-muted);
}

tr:hover td {
  background-color: rgba(245, 158, 11, 0.04);
}

/* Sidebar */
.guide-sidebar {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.sidebar-widget {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.widget-title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--secondary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.quick-links-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.quick-links-list li {
  padding: 0.5rem 0;
  border-bottom: 1px dashed var(--border-color);
}

.quick-links-list li:last-child {
  border-bottom: none;
}

.quick-links-list a {
  color: var(--text-main);
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.quick-links-list a:hover {
  color: var(--secondary);
}

.helpline-box {
  background: linear-gradient(135deg, #0f2942 0%, #1e3a8a 100%);
  color: #fff;
  border-radius: var(--radius-md);
  padding: 1.5rem;
  text-align: center;
}

.helpline-number {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--accent);
  margin: 0.5rem 0;
  letter-spacing: 0.5px;
}

/* ==========================================================================
   FAQ Section
   ========================================================================== */
.faq-section {
  padding: 3.5rem 0;
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
}

.faq-container {
  max-width: 850px;
  margin: 0 auto;
}

.faq-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin-bottom: 1rem;
  overflow: hidden;
  background-color: var(--bg-card);
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.25rem 1.5rem;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  transition: var(--transition);
}

.faq-question:hover {
  background-color: var(--bg-subtle);
}

.faq-icon {
  font-size: 1.25rem;
  transition: transform 0.25s ease;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  padding: 0 1.5rem;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s cubic-bezier(0.4, 0, 0.2, 1), padding 0.3s ease;
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.65;
}

.faq-item.active .faq-answer {
  padding: 0.5rem 1.5rem 1.25rem;
  max-height: 500px;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
  background-color: #091422;
  color: #cbd5e1;
  padding-top: 4rem;
  margin-top: auto;
  border-top: 4px solid var(--secondary);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.25fr;
  gap: 2.5rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: #94a3b8;
  font-size: 0.88rem;
  margin-top: 1rem;
  line-height: 1.6;
}

.footer-col h4 {
  color: #f8fafc;
  font-size: 1.05rem;
  margin-bottom: 1.25rem;
  position: relative;
  padding-bottom: 0.5rem;
}

.footer-col h4::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 32px;
  height: 2px;
  background-color: var(--secondary);
}

.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-links li {
  margin-bottom: 0.5rem;
}

.footer-links a {
  color: #94a3b8;
  font-size: 0.88rem;
}

.footer-links a:hover {
  color: var(--accent);
  padding-left: 4px;
}

.disclaimer-box {
  background-color: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.78rem;
  color: #94a3b8;
  line-height: 1.5;
}

.footer-bottom {
  background-color: #050b14;
  padding: 1.5rem 0;
  font-size: 0.8125rem;
  color: #64748b;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.footer-bottom .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

/* Mobile Sticky Action Bar */
.mobile-sticky-bar {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 0.65rem 1rem;
  z-index: 999;
  box-shadow: 0 -4px 10px rgba(0, 0, 0, 0.1);
}

.mobile-sticky-bar-inner {
  display: flex;
  gap: 0.5rem;
}

.mobile-sticky-bar .btn {
  flex: 1;
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */
@media (max-width: 992px) {
  .hero-grid {
    grid-template-columns: 1fr;
  }
  .content-layout {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .mobile-menu-toggle {
    display: flex;
  }
  .main-nav {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    padding: 1.5rem;
    flex-direction: column;
    align-items: stretch;
    box-shadow: var(--shadow-lg);
  }
  .main-nav.show {
    display: flex;
  }
  .nav-links {
    flex-direction: column;
    gap: 0.75rem;
  }
  .direct-buttons-grid {
    grid-template-columns: 1fr;
  }
  .articles-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .mobile-sticky-bar {
    display: block;
  }
  body {
    padding-bottom: 64px; /* Space for sticky bar */
  }
  .gov-top-bar .top-bar-links {
    display: none;
  }
}

body.script:
  //
/**
 * Rajasthan SSO Guide - Interactive Features
 * High-performance, vanilla JavaScript (no dependencies)
 */

document.addEventListener('DOMContentLoaded', () => {
  initTheme();
  initMobileMenu();
  initFaqAccordion();
  initSsoValidator();
  initServiceFilter();
  initCopyButtons();
});

// 1. Theme Toggle (Dark / Light Mode)
function initTheme() {
  const themeToggle = document.getElementById('themeToggle');
  if (!themeToggle) return;

  const savedTheme = localStorage.getItem('theme') || 'light';
  document.documentElement.setAttribute('data-theme', savedTheme);
  updateThemeIcon(savedTheme);

  themeToggle.addEventListener('click', () => {
    const currentTheme = document.documentElement.getAttribute('data-theme');
    const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('theme', newTheme);
    updateThemeIcon(newTheme);
  });
}

function updateThemeIcon(theme) {
  const themeToggle = document.getElementById('themeToggle');
  if (!themeToggle) return;
  themeToggle.innerHTML = theme === 'dark' 
    ? '☀️ <span class="sr-only" style="display:none">Light</span>' 
    : '🌙 <span class="sr-only" style="display:none">Dark</span>';
}

// 2. Mobile Menu Toggle
function initMobileMenu() {
  const toggleBtn = document.getElementById('mobileMenuToggle');
  const mainNav = document.getElementById('mainNav');
  if (!toggleBtn || !mainNav) return;

  toggleBtn.addEventListener('click', () => {
    const isExpanded = toggleBtn.getAttribute('aria-expanded') === 'true';
    toggleBtn.setAttribute('aria-expanded', !isExpanded);
    mainNav.classList.toggle('show');
  });

  // Close menu when clicking outside
  document.addEventListener('click', (e) => {
    if (!mainNav.contains(e.target) && !toggleBtn.contains(e.target) && mainNav.classList.contains('show')) {
      mainNav.classList.remove('show');
      toggleBtn.setAttribute('aria-expanded', 'false');
    }
  });
}

// 3. FAQ Accordion
function initFaqAccordion() {
  const faqItems = document.querySelectorAll('.faq-item');
  if (!faqItems.length) return;

  faqItems.forEach(item => {
    const questionBtn = item.querySelector('.faq-question');
    if (!questionBtn) return;

    questionBtn.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close other items
      faqItems.forEach(otherItem => {
        if (otherItem !== item) {
          otherItem.classList.remove('active');
          const otherBtn = otherItem.querySelector('.faq-question');
          if (otherBtn) otherBtn.setAttribute('aria-expanded', 'false');
        }
      });

      // Toggle current
      if (isActive) {
        item.classList.remove('active');
        questionBtn.setAttribute('aria-expanded', 'false');
      } else {
        item.classList.add('active');
        questionBtn.setAttribute('aria-expanded', 'true');
      }
    });
  });
}

// 4. Interactive Rajasthan SSO ID Format Validator
function initSsoValidator() {
  const checkBtn = document.getElementById('checkSsoBtn');
  const input = document.getElementById('ssoCheckInput');
  const resultBox = document.getElementById('ssoCheckResult');
  if (!checkBtn || !input || !resultBox) return;

  const validate = () => {
    const val = input.value.trim();
    resultBox.classList.remove('valid', 'invalid');

    if (!val) {
      resultBox.innerHTML = '⚠️ कृपया अपनी एसएसओ आईडी दर्ज करें (Please enter an SSO ID to check).';
      resultBox.classList.add('invalid', 'show');
      return;
    }

    // SSO ID Rules:
    // Alphanumeric with optional dot or underscore, length 4-30 chars, no spaces, no special characters
    const validPattern = /^[a-zA-Z0-9._]{4,30}$/;
    const hasSpace = /\s/.test(val);
    const hasSpecial = /[^a-zA-Z0-9._]/.test(val);

    if (hasSpace) {
      resultBox.innerHTML = '❌ <strong>अमान्य फॉर्मेट (Invalid):</strong> एसएसओ आईडी में स्पेस (खाली जगह) नहीं हो सकती। (SSO ID cannot contain spaces).';
      resultBox.classList.add('invalid', 'show');
    } else if (hasSpecial) {
      resultBox.innerHTML = '❌ <strong>अमान्य फॉर्मेट (Invalid):</strong> केवल अक्षर (A-Z), अंक (0-9), डॉट (.) और अंडरस्कोर (_) अनुमत हैं। @, #, $, & आदि मान्य नहीं हैं।';
      resultBox.classList.add('invalid', 'show');
    } else if (val.length < 4 || val.length > 30) {
      resultBox.innerHTML = `❌ <strong>अमान्य लम्बाई (Invalid Length):</strong> एसएसओ आईडी 4 से 30 अक्षरों की होनी चाहिए। वर्तमान लम्बाई: ${val.length} अक्षर।`;
      resultBox.classList.add('invalid', 'show');
    } else {
      // Valid syntax format
      let typeHint = 'Citizen SSO ID (नागरिक)';
      if (/^\d{10}$/.test(val)) {
        typeHint = 'Jan Aadhaar Linked ID (जन आधार)';
      } else if (/^[rR][jJ]/.test(val)) {
        typeHint = 'Govt Employee / RajKaj ID (राजकीय कर्मचारी)';
      }

      resultBox.innerHTML = `✅ <strong>मान्य एसएसओ आईडी फॉर्मेट (Valid Format)!</strong><br>
        ID: <code>${val}</code> | प्रकार: <strong>${typeHint}</strong><br>
        <span style="font-size: 0.85em;">आप इस आईडी से <a href="https://sso.rajasthan.gov.in" target="_blank" rel="noopener" style="text-decoration:underline; font-weight:700;">आधिकारिक SSO पोर्टल</a> पर लॉगिन कर सकते हैं।</span>`;
      resultBox.classList.add('valid', 'show');
    }
  };

  checkBtn.addEventListener('click', validate);
  input.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') validate();
  });
}

// 5. Services Filter Bar
function initServiceFilter() {
  const filterBtns = document.querySelectorAll('.filter-btn');
  const serviceCards = document.querySelectorAll('.service-card');
  if (!filterBtns.length || !serviceCards.length) return;

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const filter = btn.getAttribute('data-filter');

      serviceCards.forEach(card => {
        const cat = card.getAttribute('data-category');
        if (filter === 'all' || cat === filter) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    });
  });
}

// 6. Copy Links or Helpline
function initCopyButtons() {
  const copyBtns = document.querySelectorAll('[data-copy]');
  copyBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const textToCopy = btn.getAttribute('data-copy');
      navigator.clipboard.writeText(textToCopy).then(() => {
        const origText = btn.innerHTML;
        btn.innerHTML = 'Copied! ✓';
        setTimeout(() => {
          btn.innerHTML = origText;
        }, 2000);
      });
    });
  });
}

  //
